type Command interface {
	CommandType() uint8
	Size() int
	ToBytes(bytes []byte, index int) int
	FromBytes(bytes []byte, index int) int
}

func (reciever *Toggle) CommandType() uint8 {
	return 0
}

func (reciever *Rename) CommandType() uint8 {
	return 5
}

func (reciever *Dial) CommandType() uint8 {
	return 6
}

func (reciever *Halt) CommandType() uint8 {
	return 7
}

func EncodeCommand(message Command) []byte {
	bytes := make([]byte, 0+message.Size())
	message.ToBytes(bytes, 0)
	return bytes
}

// AppendCommand appends the encoded message to bytes.
func AppendCommand(bytes []byte, message Command) []byte {
	index := len(bytes)
	bytes = append(bytes, make([]byte, 0+message.Size())...)
	message.ToBytes(bytes, index+0)
	return bytes
}

func DecodeCommand(bytes []byte) (message Command, err error) {
	if len(bytes) == 0 {
		return nil, errors.New("packed: empty Command message")
	}
	tag := bytes[0] & 0x7
	switch tag {
	case 0:
		message = &Toggle{}
	case 5:
		message = &Rename{}
	case 6:
		message = &Dial{}
	case 7:
		message = &Halt{}
	default:
		return nil, fmt.Errorf("packed: unknown Command type %d", tag)
	}
	defer func() {
		if recover() != nil {
			message, err = nil, fmt.Errorf("packed: truncated Command type %d", tag)
		}
	}()
	if end := message.FromBytes(bytes, 0); end != len(bytes) {
		return nil, fmt.Errorf("packed: Command type %d has %d trailing bytes", tag, len(bytes)-end)
	}
	return message, nil
}

